import React from 'react';
import Dashboard from './components/Dashboard';
import BackgroundMap from './components/BackgroundMap';

function App() {
  return (
    <>
      <BackgroundMap />
      <div style={{
  position: 'absolute',
  right: '20px',
  top: '20px',
  zIndex: 1000,
  width: '320px',
  padding: '20px',
  backgroundColor: 'rgba(255, 255, 255, 0.95)',
  borderRadius: '12px',
  boxShadow: '0 0 16px rgba(0,0,0,0.3)'
}}>
  <h3 style={{ textAlign: 'center' }}>🌬️ IAQ Prediction</h3>
  <Dashboard />
</div>

    </>
  );
}

export default App;
